    val historicity: String = "",
    val virtues: List<String>,
    val quote: String,
    val meditation: String,
    val resolution: String,
    val intercessoryPrayer: String
)

object PremiumSaintContent {
    val premiumMap: Map<String, PremiumSaint> = mapOf(
        "01-27" to PremiumSaint(
            biography = "St. John Chrysostom, Bishop, Confessor, and Doctor of the Church, was Patriarch of Constantinople and is renowned as the greatest preacher in Christian history, earning the title 'Chrysostomos' (Golden-Mouthed). He was an uncompromising defender of ecclesiastical integrity, fearlessly denouncing the corruption of the imperial court and the wealthy classes, which led to his twice being exiled. His liturgical legacy remains immortalized in the Divine Liturgy of St. John Chrysostom, celebrated by millions of Eastern Catholics and Orthodox Christians daily.",
            virtues = listOf("Fearless Preaching", "Ecclesiastical Integrity", "Asceticism", "Patience in Exile"),
            quote = "Preaching makes me well. As soon as I open my mouth, all tiredness is gone. No matter how many waves beat against us, we are not afraid of drowning, for we stand upon a rock.",
            meditation = "Meditation on Courageous Truth: St. John Chrysostom did not seek the favor of kings or queens, but spoke the truth of Christ with absolute clarity, even when it cost him his freedom. Let us reflect on whether we compromise our Catholic principles to please the world, or if we possess the courage to stand firm.",
            resolution = "Speak up gently but firmly today if you hear someone mock the faith, gossip, or speak untruths, in honor of St. John's gold-mouthed courage.",
            intercessoryPrayer = "May Thy heavenly grace, we beseech Thee, O Lord, multiply upon Thy Church through the intercession of blessed John Chrysostom, Thy Bishop and Doctor; that like as his golden eloquence illuminated the world, so his prayers may protect us from all adversities. Through Christ our Lord. Amen."
        ),
        "01-31" to PremiumSaint(
            biography = "St. John Bosco (Don Bosco), Confessor of Turin, dedicated his life to the salvation, education, and spiritual fatherhood of poor young boys during the Industrial Revolution. Founder of the Salesian Society under the patronage of St. Francis de Sales, Don Bosco was gifted with extraordinary prophetic dreams, the power of miracles, and an unmatched gentleness. He taught the 'Preventive System' of education, built entirely on Reason, Religion, and Loving-Kindness, leading thousands of young souls to the sacraments, purity, and holy lives.",
            virtues = listOf("Zeal for Souls", "Loving-Kindness", "Patience", "Sacramental Devotion"),
            quote = "Fly from play-houses, from dancing-parties, from bad books, and from wicked companions. Rather, frequent the sacraments, listen to spiritual reading, and cultivate a tender devotion to the Blessed Sacrament and the Virgin Mary.",
            meditation = "Meditation on the Zeal of Don Bosco: He famously prayed, 'Give me souls, take away all else.' This is the authentic heart of the apostolic life. Let us reflect on how we can lead others to God through gentleness, cheerful service, and prayer.",
            resolution = "Examine your habits of speech today: resolve to speak only with kindness, gentleness, and encouragement to everyone you meet, in imitation of Don Bosco's gentle pastoral method.",
            intercessoryPrayer = "O God, who didst raise up Saint John, Thy Confessor, to be a father and teacher of youth, and didst will that through him, with the help of the Virgin Mary, new families should flourish in Thy Church: grant, we beseech Thee, that, inflamed by the same fire of charity, we may seek the salvation of souls and serve Thee alone. Through Christ our Lord. Amen."
        ),
        "02-02" to PremiumSaint(
            biography = "The Purification of the Blessed Virgin Mary (Candlemas) commemorates the day when the Immaculate Mother of God, in perfect obedience to the Mosaic Law, presented the Infant Jesus in the Temple forty days after His birth. On this day, the aged prophet Simeon held the Divine Child and declared Him to be 'a Light to the revelation of the Gentiles, and the glory of Thy people Israel.' Traditionally, candles are blessed and carried in solemn procession, representing Christ as the True Light of the world illuminating our spiritual darkness.",
            virtues = listOf("Perfect Obedience", "Deep Humility", "Spiritual Watchfulness", "Sacred Consecration"),
            quote = "The old man carried the Child, but the Child governed the old man. The Virgin brought forth her Maker, and bore Him in her arms, her Light and her Salvation. — St. Bernard of Clairvaux",
            meditation = "Meditation on the Light of Christ: Candlemas reminds us that Christ is the exclusive Light that dispels the darkness of sin, error, and modern secularism. As we hold the blessed candle of faith, we must ask ourselves: Is the light of grace shining brightly in my thoughts, words, and actions?",
            resolution = "Recite the Canticle of Simeon (Nunc Dimittis) slowly today, offering your eyes, heart, and entire life to be illuminated by the grace of Christ.",
            intercessoryPrayer = "O Almighty and Everlasting God, we humbly beseech Thy Majesty, that as Thine only-begotten Son was this day presented in the temple in the substance of our flesh, so we may be presented unto Thee with purified minds. Through the same Christ our Lord. Amen."
        ),
        "02-11" to PremiumSaint(
            biography = "The Apparition of the Blessed Virgin Mary Immaculate at Lourdes commemorates the eighteen appearances of Our Lady to the humble peasant girl Saint Bernadette Soubirous in the grotto of Massabielle in 1858. Revealing herself under the title 'I am the Immaculate Conception,' Our Lady called for penance, prayer, and the recitation of the Holy Rosary. She directed Bernadette to dig in the dirt, revealing a miraculous spring of water which has since healed thousands of sick pilgrims, standing as a perpetual testament to God's maternal mercy.",
            virtues = listOf("Simplicity of Heart", "Devotion to the Rosary", "Spirit of Penance", "Trust in Our Lady"),
            quote = "I do not promise to make you happy in this world, but in the next. Go, drink at the spring, and wash yourself there. Penance! Penance! Penance!",
            meditation = "Meditation on Lourdes: Our Lady chose Bernadette, a poor, uneducated girl who suffered from severe asthma, to confound the wise and powerful of the nineteenth century. Lourdes reminds us that God's power is perfected in weakness, and that our greatest strength lies in filial devotion to Mary.",
            resolution = "Pray a decade of the Rosary on your knees today for the conversion of poor sinners and the healing of the spiritually sick.",
            intercessoryPrayer = "O God, who by the Immaculate Conception of the Virgin didst prepare a worthy dwelling for Thy Son: grant, we beseech Thee, that we, who celebrate the apparition of the same Virgin, may obtain health of mind and body. Through Christ our Lord. Amen."
        ),
        "03-07" to PremiumSaint(
            biography = "St. Thomas Aquinas, known as the 'Doctor Angelicus' (Angelic Doctor), is the preeminent theologian and philosopher of the Catholic Church. A Dominican friar of noble descent, he overcame intense family opposition to embrace a life of poverty and study. Gifted with an intellect of miraculous proportions, St. Thomas synthesized Aristotelian philosophy with Christian theology, producing the monumental 'Summa Theologiae'. Despite his towering academic achievements, he was a man of profound humility, ecstatic prayer, and deep Eucharistic devotion, famously declaring before his death that all his writings were 'like straw' compared to the divine mysteries revealed to him.",
            virtues = listOf("Angelic Purity", "Supernatural Wisdom", "Deep Humility", "Eucharistic Adoration"),
            quote = "The celebration of Holy Mass has as much value as the death of Jesus on the Cross. To one who has faith, no explanation is necessary. To one without faith, no explanation is possible.",
            meditation = "Meditation on Holy Wisdom: St. Thomas studied at the foot of the Crucifix, praying and resting his head against the Tabernacle when encountering difficult theological questions. True wisdom is not merely intellectual, but supernatural, received through humility, prayer, and deep sacramental union with Christ.",
            resolution = "Before starting any study, work, or reading today, recite the prayer of St. Thomas Aquinas: 'Creator Ineffabilis' or spend 5 minutes in silent adoration of the Blessed Sacrament.",
            intercessoryPrayer = "O God, who dost glorify Thy Church with the wonderful learning of blessed Thomas, Thy Confessor, and makest it fruitful by his holy deeds: grant us, we beseech Thee, both to understand what he taught and to follow the pattern of his life. Through Christ our Lord. Amen."
        ),
        "03-12" to PremiumSaint(
            biography = "St. Gregory I (the Great), Pope, Confessor, and Doctor of the Church, was a Roman patrician who abandoned his political career to become a humble monk. Elevated to the Papacy against his will, he proved to be one of the most brilliant administrators and spiritual leaders in history. He defended Rome against invaders, initiated the conversion of England by sending St. Augustine of Canterbury, reformed the Roman Liturgy, and codified the sacred music that bears his name (Gregorian Chant). He humblingly styled himself 'Servus Servorum Dei' (Servant of the Servants of God).",
            virtues = listOf("Humility in Power", "Apostolic Vigilance", "Liturgical Zeal", "Monastic Discipline"),
            quote = "He who wishes to reach the heights must first descend to the depths. Let us fear the hidden judgments of God, and let us serve Him with all our heart.",
            meditation = "Meditation on Holy Leadership: St. Gregory the Great combined intense monastic contemplation with tireless apostolic activity. He teaches us that outward action must always overflow from a deep, silent interior life of prayer. Let us guard our prayer life against the noise of our daily obligations.",
            resolution = "Listen to or chant a Gregorian Hymn (like the Attende Domine or Salve Regina) today, meditating on the beauty and reverence of traditional liturgy.",
            intercessoryPrayer = "O God, who didst bestow on the soul of Thy servant Gregory the rewards of eternal happiness: mercifully grant that we, who are oppressed by the weight of our sins, may be relieved by his intercession. Through Christ our Lord. Amen."
        ),
        "03-17" to PremiumSaint(
            biography = "St. Patrick, Bishop and Confessor, is the glorious Apostle of Ireland. Born in Roman Britain, he was captured by Irish pirates at age sixteen and enslaved as a shepherd. During his captivity, he turned deeply to God in prayer. Escaping after six years, he received a divine call in a dream to return and convert the very pagans who had enslaved him. Consecrated a bishop, he returned to Ireland and fearlessly confronted Druid high priests, baptized thousands of converts, established countless monasteries, and successfully converted the entire nation to the Catholic faith.",
            virtues = listOf("Fearless Evangelization", "Spirit of Penance", "Boundless Charity", "Trinitarian Faith"),
            quote = "Christ be with me, Christ within me, Christ behind me, Christ before me. I bind unto myself today the strong name of the Trinity, by invocation of the same.",
            meditation = "Meditation on Faith Amid Captivity: St. Patrick's trials in captivity prepared his soul for his massive apostolic mission. He prayed a hundred times during the day and a hundred times during the night in the freezing woods of Ireland. Our own sufferings, when offered to God, become the fertile ground of our sanctification.",
            resolution = "Recite St. Patrick’s Breastplate prayer today, asking for spiritual protection and the conversion of those who do not know Christ.",
            intercessoryPrayer = "O God, who didst vouchsafe to send blessed Patrick, Thy Bishop and Confessor, to preach Thy glory to the Gentiles: grant, through his merits and intercession, that what Thou commandest us to do, we may by Thy mercy be enabled to perform. Through Christ our Lord. Amen."
        ),
        "03-19" to PremiumSaint(
            biography = "St. Joseph, the Chaste Spouse of the Blessed Virgin Mary and Foster-Father of Jesus Christ, is the patron of the Universal Church. Chosen from the lineage of King David, Joseph was a 'just man' of profound silence, unquestioning obedience, and virginal purity. He protected the Virgin Mother and nurtured the Divine Child, guarding them during the Flight into Egypt and laboring as a carpenter in Nazareth. St. Joseph represents the ideal of the interior life, executing the grandest designs of God without uttering a single recorded word in Scripture. He died peacefully in the arms of Jesus and Mary, making him the patron of a happy death.",
            virtues = listOf("Perfect Obedience", "Virginal Chastity", "Holy Silence", "Diligence in Labor"),
            quote = "He who was subject to Joseph on earth now refuses him nothing in heaven. Go to Joseph with confidence in all your needs. — St. Teresa of Avila",
            meditation = "Meditation on the Silence of St. Joseph: Joseph's life was a sanctuary of holy silence, allowing him to hear the voice of the angels and remain in constant contemplation of the Incarnate Word. In our loud, distracted world, let us seek to cultivate a quiet heart wherein God may dwell and speak.",
            resolution = "Dedicate today's work entirely to St. Joseph the Worker, performing every task with silence, diligence, and perfection, offering it as a sacrifice of praise.",
            intercessoryPrayer = "We beseech Thee, O Lord, that we may be assisted by the merits of the Spouse of Thy most holy Mother, so that what of ourselves we cannot obtain, may be granted us by his intercession. Who livest and reignest world without end. Amen."
        ),
        "03-21" to PremiumSaint(
            biography = "St. Benedict of Nursia is the Patriarch of Western Monasticism and Co-Patron of Europe. Fleeing the moral decay of Rome, he lived as a hermit in a cave at Subiaco before founding twelve monasteries, most notably Monte Cassino. He wrote the famous 'Rule of St. Benedict', a masterpiece of spiritual discretion and pastoral wisdom based on the twin pillars of 'Ora et Labora' (Prayer and Work). Gifted with absolute power over demons, prophecy, and miracles, St. Benedict tamed the wild, pagan tribes of Europe and preserved classical civilization through the dedication of his monastic sons.",
            virtues = listOf("Spiritual Discretion", "Stability of Heart", "Discipline", "Zealous Prayer"),
            quote = "Prefer nothing whatever to Christ, and may He bring us all together to everlasting life. Let them prefer nothing to the work of God (the Divine Office).",
            meditation = "Meditation on the Order of Life: St. Benedict structured monastic life so that every hour was consecrated to God through prayer, manual labor, or sacred reading. Let us reflect on how we can bring holy order, discipline, and stability to our own lives, refusing to let sloth or distraction rob us of our spiritual focus.",
            resolution = "Create a structured spiritual schedule for your day, committing to fixed times for morning prayer, evening examination, and sacred reading, and adhere to it strictly.",
            intercessoryPrayer = "May the intercession of the blessed Abbot Benedict, we beseech Thee, O Lord, commend us unto Thee: that what we cannot obtain by our own merits, we may gain by his protection. Through Christ our Lord. Amen."
        ),
        "03-25" to PremiumSaint(
            biography = "The Annunciation of the Blessed Virgin Mary celebrates the supreme pivotal moment in human history when the Archangel Gabriel was sent by God to Nazareth. Announcing that Mary had been chosen to bear the Savior of the world, he awaited her consent. With her profound and humble declaration, 'Ecce Ancilla Domini, fiat mihi secundum verbum tuum' (Behold the handmaid of the Lord, let it be done to me according to thy word), the Holy Ghost overshadowed her, and the Eternal Word became Flesh in her virginal womb. This feast is the celebration of the Incarnation of Our Lord Jesus Christ.",
            virtues = listOf("Absolute Surrender", "Spiritual Humility", "Profound Receptive Faith", "Purity"),
            quote = "At the message of the Angel, the Virgin believed, conceived, and gave birth to the Savior of the world, remaining forever inviolate. — St. Augustine of Hippo",
            meditation = "Meditation on the Divine Fiat: In her Fiat, Mary surrendered her entire destiny, her honor, and her physical body to the divine plan. This act of perfect faith restored what Eve had broken through pride and disobedience. Are we willing to say 'Fiat' to the painful or mysterious elements of God's providence in our lives today?",
            resolution = "Recite the Angelus prayer at noon today with profound reverence, genuflecting at the words: 'And the Word was made flesh, and dwelt among us.'",
            intercessoryPrayer = "O God, who didst will that Thy Word should take flesh in the womb of the Blessed Virgin Mary at the message of an Angel: grant to us Thy suppliants, that we who believe her to be truly the Mother of God, may be aided by her intercession with Thee. Through the same Christ our Lord. Amen."
        ),
        "04-25" to PremiumSaint(
            biography = "St. Mark, Evangelist and Martyr, was a disciple of St. Peter and accompanied him during his preaching in Rome. At the request of the Roman converts, he composed the first Gospel, reflecting the eyewitness testimony of St. Peter himself. St. Mark later traveled to Alexandria, Egypt, establishing the patriarchal see and converting thousands through his miracles and teaching. He was brutally martyred by a pagan mob who dragged him through the stony streets of Alexandria until he breathed his last. His feast is also celebrated with the 'Greater Rogation' procession, during which the litany is sung to beg God's blessing on the earth.",
            virtues = listOf("Apostolic Fidelity", "Zeal for the Scriptures", "Pastoral Courage", "Spirit of Penance"),
            quote = "The lion of Alexandria preached the uncompromised Gospel of Christ with apostolic zeal, watering the foundation of the Church with his own blood. — St. Jerome",
            meditation = "Meditation on Apostolic Stewardship: St. Mark took down the sermons of St. Peter, preserving the raw, powerful truth of Christ's earthly life for all generations. He teaches us to cherish the Sacred Scriptures as living, divine words, and to be faithful stewards of the truths passed down to us.",
            resolution = "Read the entire first chapter of the Gospel of St. Mark today, meditating on the urgent, active power of Christ's ministry.",
            intercessoryPrayer = "O God, who didst exalt blessed Mark, Thy Evangelist, by the grace of preaching Thy Gospel: grant, we beseech Thee, that we may both profit by his teaching and be defended by his prayers. Through Christ our Lord. Amen."
        ),
        "04-30" to PremiumSaint(
            biography = "St. Catherine of Siena, Virgin, is a Doctor of the Church and one of the greatest mystics in history. A member of the Dominican Third Order, she lived a life of intense asceticism, prayer, and union with Christ, receiving the invisible stigmata and the mystical ring of spiritual marriage. Though young and uneducated, her divine wisdom compelled her to act as a counselor to Popes, successfully persuading Pope Gregory XI to return the Papal See from Avignon to Rome. Her spiritual masterpiece, 'The Dialogue', contains sublime mystical revelations dictated during her ecstasies.",
            virtues = listOf("Mystical Union", "Zeal for the Papacy", "Intense Prayer", "Fearless Charity"),
            quote = "Be who God meant you to be and you will set the world on fire! Out of darkness, light is made. Nothing great is ever achieved without much enduring.",
            meditation = "Meditation on the Fire of Love: St. Catherine's soul was consumed by a holy fire of love for Jesus and His Church. She saw the Church as the precious Bride of Christ and wept over the sins of its ministers. Let us pray today for the purification, renewal, and fortification of the holy priesthood.",
            resolution = "Offer a prayer of reparation today for the sins of the clergy, and write down a concrete resolution to grow in personal holiness.",
            intercessoryPrayer = "Grant, we beseech Thee, O Almighty God, that we who celebrate the solemnity of blessed Catherine, Thy Virgin, may rejoice in her yearly festival and profit by the example of her outstanding virtue. Through Christ our Lord. Amen."
        ),
        "05-04" to PremiumSaint(
            biography = "St. Monica, Widow, is the immortal model of maternal prayer and perseverance. Born in North Africa, she was married to a pagan Roman official named Patricius, whom she eventually won to Christ through her patience and gentleness. Her greatest sorrow was her brilliant but rebellious son, Augustine, who fell into heresy and a life of moral dissipation. For seventeen years, Monica followed Augustine across Carthage, Rome, and Milan, weeping and offering continuous prayers and fasts for his conversion. Her prayers were answered when St. Ambrose baptized Augustine, who went on to become one of the greatest Doctors of the Church.",
            virtues = listOf("Unshakable Perseverance", "Maternal Tears", "Patient Gentleness", "Intercessory Prayer"),
            quote = "Nothing is far from God. Son of these tears, it is impossible that you should perish! All I wished was that I might die a Catholic Christian.",
            meditation = "Meditation on Persistent Prayer: St. Monica's life teaches us that God never ignores the tears of a mother or the persistence of an intercessor. When our prayers seem unanswered, God is often testing our faith and enlarging our capacity for grace. Let us persist in praying for the conversion of our loved ones.",
            resolution = "Offer your principal prayer or Mass attendance today specifically for someone you know who has fallen away from the Catholic faith.",
            intercessoryPrayer = "O God, the comforter of the sorrowful and the salvation of them that hope in Thee, who didst mercifully accept the pious tears of blessed Monica for the conversion of her son Augustine: grant us, by their united intercession, to bewail our sins and obtain Thy merciful pardon. Through Christ our Lord. Amen."
        ),
        "05-26" to PremiumSaint(
            biography = "St. Philip Neri, Confessor, is the beloved 'Apostle of Rome' and founder of the Congregation of the Oratory. Living in Rome during the Counter-Reformation, he transformed the city through his infectious joy, humility, and constant preaching of the Gospel on the streets. During Pentecost in 1544, a miraculous ball of fire entered his mouth and expanded his heart so intensely that two of his ribs were permanently broken. St. Philip was renowned for his power to read souls, his ecstatic levitations, and his supernatural humor, which he used to shatter the pride of his disciples.",
            virtues = listOf("Supernatural Joy", "Profound Humility", "Eucharistic Love", "Spiritual Cheerfulness"),
            quote = "Cheerfulness strengthens the heart and makes us persevere in a good life; wherefore the servant of God ought always to be in good spirits. Humility is the mother of all virtues.",
            meditation = "Meditation on Christian Joy: St. Philip Neri proved that holiness is not sad or gloomy, but joyful and inviting. True joy is a fruit of the Holy Ghost, born from a pure conscience and a heart detached from earthly desires. Let us cultivate a cheerful heart in our daily duties.",
            resolution = "Refuse to complain or speak of any hardship today; instead, greet every cross and every person with a warm, supernatural cheerfulness.",
            intercessoryPrayer = "O God, who didst raise Thy blessed Confessor Philip to the glory of Thy saints: mercifully grant that we, who rejoice in his festival, may benefit by the example of his virtues. Through Christ our Lord. Amen."
        ),
        "05-31" to PremiumSaint(
            biography = "The Queenship of the Blessed Virgin Mary, established in the Roman Calendar by Pope Pius XII in 1954, celebrates Mary's royal dignity as Queen of Heaven and Earth. Having shared intimately in the Passion of her Son, she was assumed into heaven and crowned by the Holy Trinity as Queen of Angels, Saints, and all Creation. Sitting at the right hand of her Divine Son, she reigns with maternal love, acting as the Mediatrix of all Graces and our most powerful advocate. Her queenship is a reign of mercy, peace, and spiritual victory.",
            virtues = listOf("Regal Humility", "Maternal Mediation", "Perfect Confidence", "Spiritual Victory"),
            quote = "The Virgin Mary is the Queen of Heaven and Earth, because she is the Mother of the King of Kings. Fear not, for our Queen is our Mother, and she reigns with maternal love.",
            meditation = "Meditation on the Queen of Mercy: Unlike earthly rulers who reign with force, Queen Mary reigns with the power of maternal love. She is the 'Refuge of Sinners' and the 'Gate of Heaven.' When we submit our lives to her royal protection, we are brought safely to the feet of our True King, Jesus Christ.",
            resolution = "Recite the Hail Holy Queen (Salve Regina) or the Litany of Loreto slowly tonight, acknowledging Mary as the sovereign Queen of your heart and family.",
            intercessoryPrayer = "O Almighty and Eternal God, who hast given us the Mother of Thy Son, Our Lord Jesus Christ, to be our Queen and Mother: mercifully grant, that under her protection, we may attain to the glory of Thy heavenly kingdom. Through the same Christ our Lord. Amen."
        ),
        "06-24" to PremiumSaint(
            biography = "The Nativity of St. John the Baptist celebrates the miraculous birth of the Precursor of Our Lord to the elderly and barren parents Zacharias and Elizabeth. Sanctuated in his mother's womb during the Visitation, John was born to prepare the way for the Messiah. He lived as a severe ascetic in the wilderness, preaching repentance and baptizing in the Jordan, famously declaring of Christ, 'He must increase, but I must decrease.' He is the only saint, besides the Blessed Virgin Mary, whose physical birth is celebrated with a major liturgical feast.",
            virtues = listOf("Severe Penance", "Profound Humility", "Uncompromising Truth", "Spiritual Zeal"),
            quote = "John was the voice, but Christ is the eternal Word who was in the beginning. John was a torch burning for a time, but Christ is the Light that lighteth every man. — St. Augustine of Hippo",
            meditation = "Meditation on the Voice in the Wilderness: St. John the Baptist was a voice pointing exclusively to Christ. He sought no glory, no comfort, and no earthly recognition. In our lives, do we seek to be noticed and praised, or do we, like John, seek to decrease so that Christ may increase in us?",
            resolution = "Examine your lifestyle: make a concrete sacrifice of comfort today (such as taking a cold shower or skipping a snack) as a penance and act of spiritual preparation.",
            intercessoryPrayer = "O God, who hast made this day honorable to us by the birth of blessed John: grant to Thy people the grace of spiritual joys, and direct the minds of all the faithful into the way of eternal salvation. Through Christ our Lord. Amen."
        ),
        "06-29" to PremiumSaint(
            biography = "SS. Peter and Paul, Apostles and Martyrs, are the twin pillars of the Catholic Church. St. Peter, selected by Christ as the Prince of the Apostles and the first Pope, received the keys of the Kingdom of Heaven. St. Paul, the Apostle to the Gentiles, converted from a fierce persecutor into an untiring evangelist who traversed the Roman Empire preaching the Gospel. Both sealed their glorious missions with martyrdom in Rome under Emperor Nero around 67 A.D.—Peter crucified upside down out of humility, and Paul beheaded with the sword, consecrating Rome to Christ.",
            virtues = listOf("Unshakable Faith", "Apostolic Zeal", "Patience in Suffering", "Heroic Martyrdom"),
            quote = "Where Peter is, there is the Church; and where the Church is, there is no death, but life eternal. — St. Ambrose",
            meditation = "Meditation on the Apostolic Pillars: Peter represents the structural authority and unity of the Church, while Paul represents its missionary fire and theological depth. Together, they demonstrate that true apostolicity requires both firm fidelity to the hierarchy and a burning zeal to spread the truth. Let us pray for the Pope and the bishops today.",
            resolution = "Offer a prayer of fidelity for the reigning Sovereign Pontiff today, and spend 10 minutes studying traditional Church dogma or an encyclical.",
            intercessoryPrayer = "O God, who didst consecrate this day by the martyrdom of Thine Apostles Peter and Paul: grant that Thy Church may in all things follow their precepts, through whom she received the first beginnings of the faith. Through Christ our Lord. Amen."
        ),
        "07-31" to PremiumSaint(
            biography = "St. Ignatius of Loyola, a Spanish nobleman and soldier, underwent a profound spiritual conversion while recovering from a battle wound at the siege of Pamplona. Retiring to a cave in Manresa, he spent months in intense penance and contemplation, during which he received divine illuminations that formed the basis of his legendary 'Spiritual Exercises'. Founder of the Society of Jesus (the Jesuits), St. Ignatius established an apostolic army dedicated to the defense and propagation of the Catholic faith under the absolute obedience to the Sovereign Pontiff. His life was defined by the maxim 'Ad Maiorem Dei Gloriam'—for the greater glory of God.",
            virtues = listOf("Apostolic Zeal", "Absolute Consecration", "Spiritual Discernment", "Fortitude"),
            quote = "Ad Maiorem Dei Gloriam (For the greater glory of God). Receive, O Lord, all my liberty. Take my memory, my understanding, and my entire will. You have given them to me; to You, O Lord, I restore them.",
            meditation = "Meditation on Holy Consecration: St. Ignatius taught that man is created to praise, reverence, and serve God Our Lord, and by this means to save his soul. All other things on the face of the earth are created for man to help him prosecute the end for which he is created. Let us examine whether we are using the gifts of this world purely as stepping stones to God, or if we have allowed them to become obstacles.",
            resolution = "Recite the Suscipe prayer of St. Ignatius slowly today, surrendering your liberty, memory, intellect, and will to Christ, and make a detailed examination of conscience tonight.",
            intercessoryPrayer = "O God, who for the propagation of the greater glory of Thy Name, didst by blessed Ignatius strengthen Thy Church militant with a new army: grant that we, fighting by his help and imitation on earth, may deserve to be crowned with him in heaven. Through Christ our Lord. Amen."
        ),
        "08-10" to PremiumSaint(
            biography = "St. Lawrence, Deacon and Martyr, was one of the seven deacons of the Roman Church under Pope St. Sixtus II. During the persecution of Valerian, the prefect of Rome demanded that Lawrence hand over the treasures of the Church. Lawrence gathered the poor, the sick, the blind, and the lame, declaring, 'Behold the treasures of the Church!' Furious, the prefect condemned him to be slowly roasted alive on a giant iron gridiron. Lawrence endured the agonizing death with superhuman courage and legendary wit, famously joking, 'I am well-done on this side; turn me over!'",
            virtues = listOf("Love for the Poor", "Superhuman Fortitude", "Holy Cheerfulness", "Deaconal Fidelity"),
            quote = "The treasures of the Church are the poor, whom Christ called blessed. I am already roasted on one side, turn me over and eat!",
            meditation = "Meditation on the Treasures of the Church: St. Lawrence saw the face of Christ in the poor and marginalized. His physical suffering was transformed into a spiritual offering because his heart was detached from all earthly wealth. Let us reflect on our own attachments to luxury and comfort.",
            resolution = "Make an alms offering or donate food/clothing to the poor today, honoring St. Lawrence’s love for the treasures of the Church.",
            intercessoryPrayer = "Enable us, we beseech Thee, O Lord, to extinguish the flames of our vices, as Thou didst grant to blessed Lawrence to overcome the fiery torments of his executioners. Through Christ our Lord. Amen."
        ),
        "08-15" to PremiumSaint(
            biography = "The Assumption of the Blessed Virgin Mary is the ancient Catholic dogma celebrating Mary's bodily assumption into heaven at the end of her earthly course. Because she was preserved from all stain of original sin, she was not subject to the corruption of the grave. Taken up body and soul into the celestial court by her Divine Son, she was exalted above all choirs of angels and crowned Queen of Heaven, standing as the ultimate sign of hope and resurrection for the Church Militant.",
            virtues = listOf("Purity of Soul", "Heavenly Desire", "Spiritual Exaltation", "Filial Hope"),
            quote = "Today the Holy Virgin is assumed into heaven, and the heavenly hosts rejoice with eternal triumph, celebrating the Mother of God. — St. John of Damascus",
            meditation = "Meditation on our Heavenly Home: The Assumption teaches us that our true homeland is not this passing world, but heaven. Mary has gone before us to prepare our way, acting as our motherly advocate. Let us lift our hearts above the trials of this world and set our desires on eternity.",
            resolution = "Recite the glorious mysteries of the Rosary today, meditating deeply on the Assumption and Coronation of Our Lady.",
            intercessoryPrayer = "O Almighty and Eternal God, who hast taken up the Immaculate Virgin Mary, Mother of Thy Son, body and soul into heavenly glory: grant, we beseech Thee, that always keeping our minds fixed on things above, we may deserve to be partakers of her glory. Through the same Christ our Lord. Amen."
        ),
        "08-28" to PremiumSaint(
            biography = "St. Augustine, Bishop, Confessor, and Doctor of the Church, is one of the most brilliant intellects and influential theologians in human history. After living a wild, rebellious youth entangled in Manichaean heresy and moral sin, he was won to the Catholic faith through the tireless tears of his mother, St. Monica, and the preaching of St. Ambrose. Baptized at age thirty-three, he became Bishop of Hippo in North Africa, dedicating his life to defending the Church against heresies, writing monumental classics like 'Confessions' and 'The City of God,' and articulating the profound doctrines of grace, the Trinity, and Christian love.",
            virtues = listOf("Profound Penance", "Intellectual Humility", "Burning Love for Truth", "Pastoral Zeal"),
            quote = "Late have I loved Thee, O Beauty so ancient and so new, late have I loved Thee! Our hearts are restless, O Lord, until they rest in Thee.",
            meditation = "Meditation on Conversion: St. Augustine teaches us that no sinner is beyond the reach of divine grace. His brilliant mind found no peace until he surrendered his heart completely to Christ. Let us reflect on our own 'restless hearts' and seek our rest exclusively in God.",
            resolution = "Spend 15 minutes today in quiet contemplation, reading a passage from St. Augustine’s Confessions or meditating on the gift of divine grace.",
            intercessoryPrayer = "Give ear to our prayers, O Almighty God, and through the intercession of blessed Augustine, Thy Confessor and Bishop, mercifully grant the abundance of Thy grace to those in whom Thou hast inspired a hope of salvation. Through Christ our Lord. Amen."
        ),
        "09-14" to PremiumSaint(
            biography = "The Exaltation of the Holy Cross commemorates the historic recovery of the True Cross of Christ by Emperor Heraclius in 629 A.D., after it had been captured by the Persians. Carrying the sacred wood barefoot and dressed in sackcloth, the Emperor restored it to the Church of the Holy Sepulchre in Jerusalem. This feast celebrates the Cross as the instrument of our redemption, the ultimate symbol of victory over sin and death, and the glorious banner under which all Christians fight.",
            virtues = listOf("Love of the Cross", "Public Witness", "Reparation for Sin", "Spiritual Victory"),
            quote = "We adore Thee, O Christ, and we bless Thee; because by Thy Holy Cross Thou hast redeemed the world. Hail, O Cross, our only hope!",
            meditation = "Meditation on the Cross: The Cross is not a sign of defeat, but of infinite love and victory. To follow Christ, we must daily embrace our own crosses—our trials, sicknesses, and humiliations—knowing that they are the key to our resurrection. Let us look upon the Crucifix with love, not fear.",
            resolution = "Make a slow, deliberate, and reverent Sign of the Cross today whenever you hear an ambulance, pass a church, or begin your prayers.",
            intercessoryPrayer = "O God, who didst make this day honorable to us by the yearly solemnity of the Exaltation of the Holy Cross: grant, we beseech Thee, that we may deserve to enjoy the rewards of her redemption in heaven, whose mystery we have known on earth. Through Christ our Lord. Amen."
        ),
        "09-29" to PremiumSaint(
            biography = "The Dedication of Saint Michael the Archangel (Michaelmas) honors the Prince of the Heavenly Host, the guardian angel of the Church, and the defender of souls. Scripture records St. Michael leading the faithful angels in the great celestial battle against Lucifer, casting him out of heaven with the war-cry 'Quis ut Deus?' (Who is like God?). Michaelmas traditionally marks the dedication of his basilica on the Salarian Way in Rome, calling the Church Militant to invoke his powerful protection against the spiritual wickedness and snares of the devil.",
            virtues = listOf("Angelic Humility", "Spiritual Combativeness", "Fidelity to God", "Uncompromising Zeal"),
            quote = "Quis ut Deus? (Who is like God?). Saint Michael the Archangel, defend us in battle, be our protection against the malice and snares of the devil.",
            meditation = "Meditation on Spiritual Warfare: We are engaged in a perpetual spiritual combat against invisible enemies. St. Michael stands as our supreme ally, holding the sword of divine justice and the shield of humility. Let us invoke him daily, especially in moments of severe temptation.",
            resolution = "Recite the St. Michael prayer slowly and aloud three times today, asking him to guard your mind, heart, and family.",
            intercessoryPrayer = "O God, who in a wonderful order hast ordained the services of Angels and men: mercifully grant, that as Thy holy Angels always do Thee service in heaven, so by Thy appointment they may succor and defend us on earth. Through Christ our Lord. Amen."
        ),
        "10-03" to PremiumSaint(
            biography = "St. Therese of the Child Jesus, Virgin, known as the 'Little Flower,' was a Carmelite nun of Lisieux who died at the age of twenty-four. She formulated the 'Little Way' of spiritual childhood—a path of absolute trust, simplicity, and love, consisting of performing the smallest daily actions with extraordinary love for God. She promised to spend her heaven doing good upon earth, letting fall 'a shower of roses' upon those who invoke her. Pope Pius XI declared her the patroness of all missions and the greatest saint of modern times.",
            virtues = listOf("Spiritual Childhood", "Absolute Trust", "Simplicity of Heart", "Hidden Sacrifice"),
            quote = "My way is all confidence and love. I will spend my heaven doing good upon earth. I will let fall a shower of roses. Love is repaid by love alone.",
            meditation = "Meditation on the Little Way: St. Therese proved that holiness does not require extraordinary physical penances or spectacular deeds. It requires that we become small, trusting in God's mercy as a child trusts its father, and offering our tiny daily crosses as roses of love to Jesus.",
            resolution = "Perform a hidden act of kindness today for someone who annoys you, or perform a tedious task with perfect love and without complaining.",
            intercessoryPrayer = "O Lord, who didst say: 'Unless you become as little children, you shall not enter into the kingdom of heaven': grant us, we beseech Thee, so to follow the footsteps of the blessed Virgin Therese in humility and simplicity of heart, that we may attain to Thy eternal rewards. Through Christ our Lord. Amen."
        ),
        "10-04" to PremiumSaint(
            biography = "St. Francis of Assisi, Confessor, is one of the most beloved saints in history. The son of a wealthy merchant, he renounced his inheritance to embrace 'Lady Poverty,' living as a beggar and preaching peace and repentance. He founded the Order of Friars Minor (Franciscans), revitalizing the medieval Church through his literal adherence to the Gospel. Gifted with an extraordinary love for creation, he was blessed with the holy stigmata (the wounds of Christ) on Mount Alvernia in 1224, becoming the first recorded stigmatist in history, bearing the marks of Christ's Passion in his own flesh.",
            virtues = listOf("Profound Poverty", "Seraphic Love", "Profound Humility", "Stigmatic Conformity"),
            quote = "Preach the Gospel at all times and when necessary use words. It is in giving that we receive; it is in pardoning that we are pardoned; and it is in dying that we are born to eternal life. My God and my All!",
            meditation = "Meditation on Seraphic Love: St. Francis was called 'Seraphic' because his heart burned with the fiery love of the angels. His poverty was not merely a lack of money, but a complete detachment from self-will and pride, allowing Christ to fill his soul entirely. Let us check what earthly attachments we need to cast away.",
            resolution = "Examine your lifestyle: identify one luxury, convenience, or source of vanity today and voluntarily renounce it, offering the sacrifice to God.",
            intercessoryPrayer = "O God, who by the merits of blessed Francis dost enrich Thy Church with a new family: grant us by his imitation to despise earthly things, and ever to rejoice in the participation of Thy heavenly gifts. Through Christ our Lord. Amen."
        ),
        "11-01" to PremiumSaint(
            biography = "The Solemnity of All Saints (All Hallows' Day) honors all the saints of heaven, both known and unknown. From the glorious Apostles, courageous Martyrs, and brilliant Doctors to the millions of hidden souls who lived lives of quiet holiness on earth, this feast celebrates the triumphant Church in heaven. It reminds the Church Militant on earth of our universal call to holiness and the reality of our communion with those who have run the race before us, awaiting our arrival in our heavenly homeland.",
            virtues = listOf("Universal Call to Holiness", "Communion of Saints", "Heavenly Aspiration", "Fidelity"),
            quote = "The saints in heaven are our true brothers and sisters; they love us, pray for us, and desire with burning charity that we join them in eternal glory. — St. Bernard of Clairvaux",
            meditation = "Meditation on our Calling: Today's feast reminds us that the saints were ordinary human beings who co-operated with extraordinary grace. They faced the same temptations, weaknesses, and trials that we do today. If they could achieve the crown of glory, so can we, through the same grace of Christ.",
            resolution = "Read the Beatitudes slowly today (St. Matthew 5:1-12) and choose one beatitude to cultivate with special focus throughout the week.",
            intercessoryPrayer = "O Almighty and Everlasting God, who hast granted us to celebrate in one solemnity the merits of all Thy Saints: we beseech Thee, that through the abundance of our intercessors, Thou wouldst bestow upon us the fullness of Thy mercy. Through Christ our Lord. Amen."
        ),
        "11-11" to PremiumSaint(
            biography = "St. Martin of Tours, Bishop and Confessor, was a Roman soldier who famously cut his military cloak in half to share it with a freezing beggar, later discovering in a dream that the beggar was Christ Himself. Leaving the military, he was baptized and became a disciple of St. Hilary, eventually being consecrated Bishop of Tours. He was a tireless apostle, destroying pagan shrines, performing miracles, and living as a monk-bishop in deep asceticism, making him one of the most popular and celebrated confessors in Europe.",
            virtues = listOf("Heroic Charity", "Apostolic Courage", "Monastic Simplicity", "Patience"),
            quote = "Lord, if Thy people still need me, I do not refuse to labor. Thy will be done. Christ is clothed in the person of the poor.",
            meditation = "Meditation on the Cloak of Charity: St. Martin's act of dividing his cloak teaches us that true charity is immediate, sacrificial, and personal. He did not wait for others to act, but saw Christ in the needy soldier. Let us ask: Do we recognize Christ in the inconvenient demands of charity today?",
            resolution = "Offer a warm, generous gift of charity to a needy person or family today, or perform a hidden service for an elderly neighbor.",
            intercessoryPrayer = "O God, who seest that we stand not by our own strength: mercifully grant, that by the intercession of blessed Martin, Thy Bishop and Confessor, we may be defended against all adversities. Through Christ our Lord. Amen."
        ),
        "12-08" to PremiumSaint(
            biography = "The Solemnity of the Immaculate Conception of the Blessed Virgin Mary celebrates the supreme dogma that Mary, from the first instant of her conception in the womb of St. Anne, was preserved from all stain of original sin by a unique privilege and grace of Almighty God, in view of the merits of Jesus Christ. Created in a state of perfect justice and filled with the fullness of grace, she is the 'New Eve'—the sinless Mother who crushed the head of the serpent under her heel.",
            virtues = listOf("Absolute Sinlessness", "Fullness of Grace", "Supernatural Purity", "Perfect Humility"),
            quote = "Thou art all fair, O Mary, and the original stain is not in thee. I am the Immaculate Conception. (Our Lady of Lourdes)",
            meditation = "Meditation on Pristine Purity: Mary’s Immaculate Conception is the dawn of our redemption, showing us what humanity looks like when completely untouched by the poison of sin. Let us fly to her maternal intercession to preserve us from mortal and venial sins, guarding our senses with holy purity.",
            resolution = "Pray the Miraculous Medal prayer three times today: 'O Mary, conceived without sin, pray for us who have recourse to thee.'",
            intercessoryPrayer = "O God, who by the Immaculate Conception of the Virgin didst prepare a worthy dwelling for Thy Son: we beseech Thee, that as by the foreseen death of Thy Son, Thou didst preserve her from all stain, so Thou wouldst permit us, purified by her intercession, to come unto Thee. Through the same Christ our Lord. Amen."
        ),
        "12-25" to PremiumSaint(
            biography = "The Nativity of Our Lord Jesus Christ (Christmas) is the solemn feast celebrating the bodily birth of the Savior of the world in a stable in Bethlehem. In the fullness of time, the Eternal Word, through whom all things were made, humbled Himself to take on our frail human nature, born of the Virgin Mary in poverty, silence, and cold. Adored by the angels, shepherds, and Magi, the Divine Infant came to rescue humanity from the exile of sin, bringing the light of divine grace to a darkened world.",
            virtues = listOf("Divine Humility", "Sacred Poverty", "Adoration", "Filial Love"),
            quote = "Christian, recognize your dignity! You have been made a partaker of the Divine Nature; do not return to your former vileness. — Pope St. Leo the Great",
            meditation = "Meditation on the Humility of God: At Christmas, the Infinite God becomes a tiny, silent Infant, dependent on a human mother for sustenance. He chose poverty, a stable, and a manger to teach us that true wealth is spiritual, and that pride is the root of our separation from Him.",
            resolution = "Spend 10 minutes tonight in silent meditation before a Nativity scene, contemplating the poverty of the stable and offering your heart as a cradle for Jesus.",
            intercessoryPrayer = "Grant, we beseech Thee, O Almighty God, that the new birth in the flesh of Thine only-begotten Son may set us free, whom the old bondage holds fast under the yoke of sin. Through the same Christ our Lord. Amen."
        ),
        "12-26" to PremiumSaint(
            biography = "St. Stephen, the Proto-Martyr (First Martyr), was one of the first seven deacons chosen by the Apostles to serve the early Church in Jerusalem. Full of faith, grace, and fortitude, he performed great wonders and signs. Confronting the Jewish Sanhedrin with fearless eloquence, he accused them of resisting the Holy Ghost. Draged outside the city to be stoned to death, he looked up and saw the heavens opened and the Son of Man standing at the right hand of God. Kneeling, he prayed for his executioners, crying out, 'Lord, lay not this sin to their charge' before falling asleep in Christ.",
            virtues = listOf("Fearless Fortitude", "Heroic Forgiveness", "Holy Eloquence", "Deaconal Service"),
            quote = "Stephen, crowned with martyrdom, conquered his executioners through love, praying for those who stoned him that they might find salvation in Christ. — St. Fulgentius of Ruspe",
            meditation = "Meditation on Forgiveness: St. Stephen’s final prayer for his executioners was so powerful that it won the grace of conversion for Saul of Tarsus (who went on to become St. Paul). Forgiveness of our enemies is the most heroic and Christ-like act we can perform, transforming persecutors into saints.",
            resolution = "Identify someone today who has hurt or offended you; pray a sincere Hail Mary for their physical and spiritual well-being, forgiving them from your heart.",
            intercessoryPrayer = "Grant us, we beseech Thee, O Lord, to imitate what we revere, that we may learn to love even our enemies; for we celebrate the birth to heaven of him who knew how to pray for his persecutors to our Lord Jesus Christ. Who livest and reignest world without end. Amen."
        )
    )
}
